import { test, expect } from '@playwright/test';

test.describe('Image Responsive Scaling on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/images');
  });

  test('should scale images down to fit the screen width on mobile devices', async ({ page }) => {
    // Set viewport to mobile width
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify image scales down
    const image = page.getByRole('img', { name: /sample image/i });
    await expect(image).toBeVisible();
    await expect(image).toHaveAttribute('width', '375px');
    await expect(image).toHaveAttribute('height', '500px');

    // Verify image maintains aspect ratio
    const aspectRatio = parseFloat(image.evaluate((el) => el.naturalWidth / el.naturalHeight).toString());
    expect(aspectRatio).toBeGreaterThan(0);

    // Verify image is not stretched
    const imageWidth = await image.evaluate((el) => el.clientWidth);
    const imageHeight = await image.evaluate((el) => el.clientHeight);
    expect(imageWidth).toBeLessThanOrEqual(375);
    expect(imageHeight).toBeLessThanOrEqual(500);

    // Verify image is visible and not cut off
    await expect(image).toBeVisible();
    await expect(image).not.toHaveClass(/cut-off/i);
  });

  test('should maintain image quality when scaling down on mobile devices', async ({ page }) => {
    // Set viewport to mobile width
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify image scales down without losing quality
    const image = page.getByRole('img', { name: /sample image/i });
    await expect(image).toBeVisible();
    const imageWidth = await image.evaluate((el) => el.clientWidth);
    const imageHeight = await image.evaluate((el) => el.clientHeight);
    const imageSize = imageWidth * imageHeight;

    // Verify image size is not excessively small
    expect(imageSize).toBeGreaterThan(10000);

    // Verify image is not pixelated
    const imageSrc = await image.evaluate((el) => el.src);
    expect(imageSrc).toContain('image/jpeg');
    expect(imageSrc).toContain('image/png');

    // Verify image is not blurry
    const imageQuality = await image.evaluate((el) => el.naturalWidth / el.naturalHeight);
    expect(imageQuality).toBeGreaterThan(0.5);
  });
});
